  provider_phone_required: {"ar":"أدخل رقم جوال صالح للتسجيل كمقدم خدمة","en":"Enter a valid phone number to register as a service provider","ur":"خدمت فراہم کنندہ کے طور پر رجسٹر ہونے کے لیے درست موبائل نمبر درج کریں","bn":"সেবাদাতা হিসেবে নিবন্ধন করতে একটি সঠিক মোবাইল নম্বর দিন","hi":"सेवा प्रदाता के रूप में रजिस्टर करने के लिए सही मोबाइल नंबर दर्ज करें","ml":"ഒരു സേവന ദാതാവായി രജിസ്റ്റർ ചെയ്യാനായി സാധുവായ ഫോൺ നമ്പർ നൽകുക","fil":"Maglagay ng wastong numero ng mobile para magparehistro bilang service provider","id":"Masukkan nomor ponsel yang valid untuk mendaftar sebagai penyedia layanan","ne":"सेवा प्रदायकको रूपमा दर्ता गर्न मान्य फोन नम्बर प्रविष्ट गर्नुहोस्","am":"እንደ አገልግሎት ሰጪ ለመመዝገብ ትክክለኛ የሞባይል ቁጥር ያስገቡ","tr":"Hizmet veren olarak kayıt olmak için geçerli bir cep telefonu numarası girin"},
  provider_area_required: {"ar":"اختر المدينة والحي الذي تعمل فيه","en":"Choose the city and neighborhood where you work","ur":"وہ شہر اور محلہ منتخب کریں جہاں آپ کام کرتے ہیں","bn":"আপনি যে শহর ও এলাকায় কাজ করেন তা বেছে নিন","hi":"वह शहर और इलाका चुनें जहाँ आप काम करते हैं","ml":"നിങ്ങൾ ജോലി ചെയ്യുന്ന നഗരവും അയൽപക്കവും തിരഞ്ഞെടുക്കുക","fil":"Piliin ang lungsod at kapitbahayan kung saan ka nagtatrabaho","id":"Pilih kota dan lingkungan tempat Anda bekerja","ne":"तपाईं काम गर्ने शहर र टोल छान्नुहोस्","am":"የሚሠሩበትን ከተማና አካባቢ ይምረጡ","tr":"Çalıştığınız şehri ve mahalleyi seçin"},
  account_phone_unavailable: {"ar":"التسجيل بالجوال غير متاح حاليًا. تواصل مع الإدارة.","en":"Phone registration is currently unavailable. Contact the administration.","ur":"فون کے ذریعے رجسٹریشن فی الحال دستیاب نہیں۔ انتظامیہ سے رابطہ کریں۔","bn":"মোবাইল দিয়ে নিবন্ধন এখন চালু নেই। প্রশাসনের সাথে যোগাযোগ করুন।","hi":"मोबाइल से रजिस्ट्रेशन अभी उपलब्ध नहीं है। एडमिन से संपर्क करें।","ml":"ഫോൺ വഴിയുള്ള രജിസ്ട്രേഷൻ നിലവിൽ ലഭ്യമല്ല. അഡ്മിനുമായി ബന്ധപ്പെടുക.","fil":"Hindi pa available ang pagpaparehistro gamit ang mobile. Makipag-ugnayan sa admin.","id":"Pendaftaran dengan nomor ponsel saat ini belum tersedia. Hubungi admin.","ne":"मोबाइलबाट दर्ता हाल उपलब्ध छैन। प्रशासनलाई सम्पर्क गर्नुहोस्।","am":"በስልክ መመዝገብ በአሁኑ ጊዜ አይቻልም። አስተዳደሩን ያነጋግሩ።","tr":"Telefonla kayıt şu anda kullanılamıyor. Yönetimle iletişime geçin."},
  account_profile_required: {"ar": "أكمل الاسم ورقم الجوال والمدينة والحي، وحدد موقعك على الخريطة.", "en": "Complete your name, phone number, city and neighborhood, and mark your location on the map.", "ur": "نام، فون، شہر اور محلہ مکمل کریں اور نقشے پر اپنا مقام منتخب کریں۔", "bn": "নাম, ফোন, শহর ও এলাকা পূরণ করুন এবং মানচিত্রে আপনার অবস্থান চিহ্নিত করুন।", "hi": "नाम, मोबाइल नंबर, शहर और इलाका भरें, और नक्शे पर अपनी जगह चुनें।", "ml": "നിങ്ങളുടെ പേര്, ഫോൺ, നഗരം, അയൽപക്കം എന്നിവ പൂരിപ്പിച്ച് മാപ്പിൽ നിങ്ങളുടെ സ്ഥാനം അടയാളപ്പെടുത്തുക.", "fil": "Kumpletuhin ang iyong pangalan, numero ng mobile, lungsod at kapitbahayan, at markahan ang iyong lokasyon sa mapa.", "id": "Lengkapi nama, nomor ponsel, kota, dan lingkungan Anda, lalu tandai lokasi Anda di peta.", "ne": "आफ्नो नाम, मोबाइल नम्बर, शहर र टोल भर्नुहोस्, र नक्सामा आफ्नो स्थान चिन्ह लगाउनुहोस्।", "am": "ስምዎን፣ የስልክ ቁጥርዎን፣ ከተማዎን እና አካባቢዎን ይሙሉ፤ በካርታው ላይም ቦታዎን ይምረጡ።", "tr": "Adınızı, telefon numaranızı, şehrinizi ve mahallenizi girin ve haritada konumunuzu işaretleyin."},
  account_location_required: {"ar": "لحفظ الموقع الافتراضي، اختر المدينة والحي وحدد موقعك على الخريطة.", "en": "To save your default location, choose the city and neighborhood and mark your location on the map.", "ur": "اپنا ڈیفالٹ مقام محفوظ کرنے کے لیے شہر اور محلہ منتخب کریں اور نقشے پر اپنا مقام منتخب کریں۔", "bn": "ডিফল্ট অবস্থান সংরক্ষণ করতে শহর ও এলাকা বেছে নিন এবং মানচিত্রে আপনার অবস্থান নির্বাচন করুন।", "hi": "डिफ़ॉल्ट जगह सहेजने के लिए शहर और इलाका चुनें और नक्शे पर अपनी जगह चुनें।", "ml": "നിങ്ങളുടെ സ്ഥിരസ്ഥിതി സ്ഥാനം സംരക്ഷിക്കാൻ നഗരവും അയൽപക്കവും തിരഞ്ഞെടുത്ത് മാപ്പിൽ നിങ്ങളുടെ സ്ഥാനം അടയാളപ്പെടുത്തുക.", "fil": "Para i-save ang default na lokasyon, piliin ang lungsod at kapitbahayan at markahan ang iyong lokasyon sa mapa.", "id": "Untuk menyimpan lokasi default, pilih kota dan lingkungan, lalu tandai lokasi Anda di peta.", "ne": "पूर्वनिर्धारित स्थान सुरक्षित गर्न शहर र टोल छान्नुहोस् र नक्सामा आफ्नो स्थान चिन्ह लगाउनुहोस्।", "am": "ነባሪ ቦታዎን ለማስቀመጥ ከተማውን እና አካባቢውን ይምረጡ፣ በካርታው ላይም ቦታዎን ይምረጡ።", "tr": "Varsayılan konumunuzu kaydetmek için şehri ve mahalleyi seçin ve haritada konumunuzu işaretleyin."},
